/**
 * Test flow for Knowledge Management trigger
 * Tests: Knowledge management trigger with knowledge article outputs
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testKnowledgeManagementTrigger = Flow(
    {
        $id: Now.ID['test_knowledge_management_trigger_flow'],
        name: 'Test Knowledge Management Trigger',
        description: 'Tests the Knowledge Management trigger for KB articles',
    },
    wfa.trigger(trigger.application.knowledgeManagement, { $id: Now.ID['test_knowledge_management_trigger'] }, {}),
    (_params) => {
        // Log knowledge article and trigger details
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_knowledge_management_log'] },
            {
                log_level: 'info',
                log_message: `Knowledge Article: ${wfa.dataPill(_params.trigger.knowledge, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Start Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)
